from typing import Union


def american_probability(value: Union[int, float, str]) -> float:
    """Return the implied probability for American odds.

    Accepts ``int``, ``float`` or a numeric string (leading/trailing
    whitespace allowed).  Raises ``ValueError`` for any other type, for
    ``None`` or ``bool``, for non‑numeric strings, for non‑finite values
    or for values whose absolute value is less than 100.

    The calculation follows the standard formula:
    * positive odds: ``100 / (value + 100)``
    * negative odds: ``-value / (-value + 100)``
    """
    # Reject bools explicitly – they are instances of int.
    if isinstance(value, bool):
        raise ValueError("bool is not a valid odds value")
    if value is None:
        raise ValueError("None is not a valid odds value")

    if isinstance(value, (int, float)):
        num = value
    elif isinstance(value, str):
        stripped = value.strip()
        if stripped == "":
            raise ValueError("empty string is not a valid odds value")
        try:
            num = float(stripped)
        except ValueError as exc:
            raise ValueError(f"string '{value}' is not a numeric odds value") from exc
    else:
        raise ValueError(f"Unsupported type {type(value).__name__} for odds value")

    if not math.isfinite(num):
        raise ValueError("odds value must be finite")
    if abs(num) < 100:
        raise ValueError("odds value must have absolute value >= 100")

    if num > 0:
        return 100.0 / (num + 100.0)
    else:
        return -num / (-num + 100.0)
