def _parse_iso(dt_str: str) -> datetime.datetime:
    """Parse an ISO‑8601 datetime string that includes timezone info.

    Accepts strings ending with ``Z`` as UTC.  Raises ``ValueError`` if
    the string cannot be parsed or if the resulting ``datetime`` is
    naive.
    """
    if not isinstance(dt_str, str):
        raise ValueError("datetime must be a string")
    s = dt_str.strip()
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    try:
        dt = datetime.datetime.fromisoformat(s)
    except Exception as exc:
        raise ValueError(f"invalid ISO datetime: {dt_str}") from exc
    if dt.tzinfo is None:
        raise ValueError(f"datetime is naive: {dt_str}")
    return dt


def select_latest(rows: Iterable[Dict[str, Any]], asof: datetime.datetime) -> Optional[Dict[str, Any]]:
    """Return the original eligible row with the latest ``observed_at``.

    * ``asof`` must be a timezone‑aware ``datetime``; otherwise a
      ``ValueError`` is raised.
    * A row is eligible if:
      - ``id`` is a non‑empty string.
      - ``odds`` is a valid American odds value.
      - ``observed_at`` and ``expires_at`` are timezone‑aware ISO
        timestamps with ``observed_at < expires_at``.
      - ``observed_at <= asof < expires_at``.
    * If multiple rows share the same latest ``observed_at``, the one
      with the lexicographically smallest ``id`` is chosen.
    * ``None`` is returned if no rows are eligible.
    """
    if not isinstance(asof, datetime.datetime) or asof.tzinfo is None:
        raise ValueError("asof must be a timezone-aware datetime")

    best_row: Optional[Dict[str, Any]] = None
    best_time: Optional[datetime.datetime] = None
    best_id: Optional[str] = None

    for row in rows:
        try:
            # Validate id
            row_id = row.get("id")
            if not isinstance(row_id, str) or row_id == "":
                raise ValueError
            # Validate odds – will raise if invalid
            american_probability(row.get("odds"))
            # Parse timestamps
            observed_at = _parse_iso(row.get("observed_at", ""))
            expires_at = _parse_iso(row.get("expires_at", ""))
            if observed_at >= expires_at:
                raise ValueError
            if not (observed_at <= asof < expires_at):
                continue
        except Exception:
            # Skip malformed or ineligible rows
            continue

        if (
            best_row is None
            or observed_at > best_time
            or (observed_at == best_time and row_id < best_id)
        ):
            best_row = row
            best_time = observed_at
            best_id = row_id

    return best_row
